function classFor(s){if(s.classId&&state.classes.some(c=>c.id===s.classId))return s.classId;const student=state.students.find(x=>x.id===s.studentId)||state.profile;const ids=(student?.classIds||[]).filter(id=>state.classes.some(c=>c.id===id));const matches=ids.filter(id=>{const level=levelOf(id);return level===s.subject||(s.subject==='alevel'&&(level==='as'&&[1,2].includes(Number(s.paper))||level==='a2'&&Number(s.paper)===4));});return matches.length===1?matches[0]:ids.length===1?ids[0]:'';}
