function parseQuestions(raw){const parts=String(raw||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean);if(parts.length>30)throw new Error('Please list no more than 30 questions.');const normalized=parts.map(x=>x.replace(/[\s().]/g,'').toLowerCase());const invalid=parts.filter((_,i)=>!/^\d{1,2}[a-z]?(?:iv|iii|ii|i|v)?$/.test(normalized[i]));if(invalid.length)throw new Error(`Write each full question, such as 2bi,2bii. Check: ${invalid.join(', ')}`);return [...new Set(normalized)];}
