function friendlyError(e){
  const code=e?.code||'';
  if(['auth/invalid-credential','auth/wrong-password','auth/user-not-found'].includes(code)) return 'Email or password was not accepted.';
  if(code==='auth/email-already-in-use') return 'This email already has an account. Choose Sign in instead.';
  if(code==='auth/weak-password') return 'Choose a stronger password with at least 6 characters.';
  if(code==='permission-denied') return 'Firebase denied access. Check that your email is verified and that you opened your own invitation link. If it still fails, ask your teacher to check the published rules.';
  return e?.message || 'Something went wrong. Please try again.';
}
function message(text,bad=false){state.notice=bad?'':text;state.error=bad?text:'';render();}
