async function ensureVerifiedToken(){
  const user=auth.currentUser;
  if(!user)throw new Error('Sign in before connecting your invitation.');
  await reload(user);
  state.user=auth.currentUser;
  if(!state.user.emailVerified)throw new Error('Open the verification email first, then return here.');
  const token=await state.user.getIdTokenResult(true);
  if(token.claims.email_verified!==true)throw new Error('Firebase has not updated your verification yet. Please wait a moment and try again.');
}
async function readCollection(ref){const snap=await getDocs(ref);return snap.docs.map(d=>({id:d.id,...d.data()}));}

async function refresh(){
  const settings=await getDoc(doc(db,'settings','app'));
  state.branding=settings.exists()?{title:settings.data().title||'Past Paper Tracker',subtitle:settings.data().subtitle||''}:state.branding;
  if(state.teacher){
    state.classes=await readCollection(collection(db,'classes'));
    state.students=await readCollection(collection(db,'students'));
  }else{
    const member=await getDoc(doc(db,'members',state.user.uid));
    if(!member.exists()){state.profile=null;state.memberId=null;state.classes=[];state.assignments=[];state.submissions=[];return;}
    state.memberId=member.data().studentId;
    const profile=await getDoc(doc(db,'students',state.memberId));
    if(!profile.exists())throw new Error('Your student record could not be found. Please ask your teacher.');
    state.profile={id:state.memberId,...profile.data()};
    state.classes=(await Promise.all((state.profile.classIds||[]).map(async id=>{const x=await getDoc(doc(db,'classes',id));return x.exists()?{id,...x.data()}:null;}))).filter(Boolean);
    state.students=[state.profile];
  }
  state.assignments=(await Promise.all(state.classes.map(c=>readCollection(collection(db,'classes',c.id,'assignments')).then(a=>a.map(x=>({...x,classId:c.id})))))).flat();
  state.submissions=state.teacher?(await Promise.all(state.students.map(s=>readCollection(collection(db,'students',s.id,'submissions')).then(a=>a.map(x=>({...x,studentId:s.id})))))).flat():(await readCollection(collection(db,'students',state.memberId,'submissions'))).map(x=>({...x,studentId:state.memberId}));
  state.questionStatus=Object.fromEntries((await readCollection(collection(db,'questionStatus'))).map(x=>[x.key,x.explained]));
  state.examTotals=Object.fromEntries((await readCollection(collection(db,'examTotals'))).map(x=>[x.id,x]));
  enrichSubmissions();
  if(!state.selectedClass||!state.classes.some(c=>c.id===state.selectedClass))state.selectedClass=state.classes[0]?.id||'';
  if(!state.scheduleClass||!state.classes.some(c=>c.id===state.scheduleClass))state.scheduleClass=state.classes[0]?.id||'';
  if(!state.freeClass||!state.classes.some(c=>c.id===state.freeClass))state.freeClass=state.classes[0]?.id||'';
  if(!state.selectedStudent||!state.students.some(s=>s.id===state.selectedStudent))state.selectedStudent=state.students[0]?.id||'';
  if(!state.reportStudent||!state.students.some(s=>s.id===state.reportStudent))state.reportStudent=state.students[0]?.id||'';
  if(!state.reportClass||!state.classes.some(c=>c.id===state.reportClass))state.reportClass=state.classes[0]?.id||'';
}
