 if(action==='show-add-class'){state.showAddClass=!state.showAddClass;render();return;}
 if(action==='show-add-student'){state.showAddStudent=!state.showAddStudent;render();return;}
 if(action==='edit-student'){state.editingStudent=b.dataset.id;state.deletingStudent='';render();return;}
