 if(el.dataset.free){const type=el.dataset.free;state['free'+type[0].toUpperCase()+type.slice(1)]=el.value;if(type==='class')state.freePaper='';if(type==='session'&&el.value==='mar')state.freeVariant='2';render();return;}
