  const assignment=state.assignments.find(a=>a.id===form.dataset.assignment),old=state.submissions.find(s=>s.id===form.dataset.id&&s.studentId===me());
  const classId=assignment?.classId||String(values.get('classId')||old?.classId||classFor(old||{})||state.freeClass),level=levelOf(classId);
  const year=Number(assignment?.year||values.get('year')||old?.year),session=assignment?.session||String(values.get('session')||old?.session||''),paper=Number(assignment?.paper||values.get('paper')||old?.paper),variant=session==='mar'?2:Number(assignment?.variant||values.get('variant')||old?.variant);
